**S3 (Simple Storage Service) Operations**

```java
// Dependencies
<dependency>
  <groupId>software.amazon.awssdk</groupId>
  <artifactId>s3</artifactId>
  <version>2.20.0</version>
</dependency>

// Configuration
@Configuration
public class AwsConfig {
  @Bean
  public S3Client s3Client() {
    return S3Client.builder()
      .region(Region.US_EAST_1)
      .credentialsProvider(DefaultCredentialsProvider.create())
      .build();
  }
}

// S3 Service
@Service
public class S3Service {
  @Autowired
  private S3Client s3Client;

  private static final String BUCKET_NAME = "my-app-bucket";

  // Upload file
  public String uploadFile(String key, InputStream inputStream, long contentLength) {
    PutObjectRequest request = PutObjectRequest.builder()
      .bucket(BUCKET_NAME)
      .key(key)
      .contentType("application/octet-stream")
      .build();

    s3Client.putObject(request, 
      RequestBody.fromInputStream(inputStream, contentLength));

    return String.format("https://%s.s3.amazonaws.com/%s", BUCKET_NAME, key);
  }

  // Download file
  public InputStream downloadFile(String key) {
    GetObjectRequest request = GetObjectRequest.builder()
      .bucket(BUCKET_NAME)
      .key(key)
      .build();

    ResponseInputStream<GetObjectResponse> response = 
      s3Client.getObject(request);

    return response;
  }

  // Generate presigned URL (temporary access)
  public String generatePresignedUrl(String key, Duration expiration) {
    S3Presigner presigner = S3Presigner.create();

    GetObjectRequest getRequest = GetObjectRequest.builder()
      .bucket(BUCKET_NAME)
      .key(key)
      .build();

    GetObjectPresignRequest presignRequest = GetObjectPresignRequest.builder()
      .signatureDuration(expiration)
      .getObjectRequest(getRequest)
      .build();

    PresignedGetObjectRequest presigned = presigner.presignGetObject(presignRequest);
    return presigned.url().toString();
  }

  // List objects
  public List<String> listFiles(String prefix) {
    ListObjectsV2Request request = ListObjectsV2Request.builder()
      .bucket(BUCKET_NAME)
      .prefix(prefix)
      .build();

    ListObjectsV2Response response = s3Client.listObjectsV2(request);

    return response.contents().stream()
      .map(S3Object::key)
      .collect(Collectors.toList());
  }

  // Delete file
  public void deleteFile(String key) {
    DeleteObjectRequest request = DeleteObjectRequest.builder()
      .bucket(BUCKET_NAME)
      .key(key)
      .build();

    s3Client.deleteObject(request);
  }
}

// Controller usage
@RestController
@RequestMapping("/api/files")
public class FileController {
  @Autowired
  private S3Service s3Service;

  @PostMapping("/upload")
  public ResponseEntity<String> uploadFile(
    @RequestParam("file") MultipartFile file
  ) throws IOException {
    String key = UUID.randomUUID().toString() + "-" + file.getOriginalFilename();

    String url = s3Service.uploadFile(
      key,
      file.getInputStream(),
      file.getSize()
    );

    return ResponseEntity.ok(url);
  }

  @GetMapping("/download/{key}")
  public ResponseEntity<Resource> downloadFile(@PathVariable String key) {
    InputStream inputStream = s3Service.downloadFile(key);

    return ResponseEntity.ok()
      .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"" + key + "\"")
      .body(new InputStreamResource(inputStream));
  }
}
```

**SQS (Simple Queue Service) Operations**

```java
// Dependencies
<dependency>
  <groupId>software.amazon.awssdk</groupId>
  <artifactId>sqs</artifactId>
  <version>2.20.0</version>
</dependency>

// Configuration
@Configuration
public class SqsConfig {
  @Bean
  public SqsClient sqsClient() {
    return SqsClient.builder()
      .region(Region.US_EAST_1)
      .credentialsProvider(DefaultCredentialsProvider.create())
      .build();
  }
}

// SQS Service
@Service
public class SqsService {
  @Autowired
  private SqsClient sqsClient;

  @Autowired
  private ObjectMapper objectMapper;

  private static final String QUEUE_URL = 
    "https://sqs.us-east-1.amazonaws.com/123456789/my-queue";

  // Send message
  public String sendMessage(Object messageBody) throws JsonProcessingException {
    String messageJson = objectMapper.writeValueAsString(messageBody);

    SendMessageRequest request = SendMessageRequest.builder()
      .queueUrl(QUEUE_URL)
      .messageBody(messageJson)
      .messageAttributes(Map.of(
        "Timestamp", MessageAttributeValue.builder()
          .dataType("String")
          .stringValue(Instant.now().toString())
          .build()
      ))
      .build();

    SendMessageResponse response = sqsClient.sendMessage(request);
    return response.messageId();
  }

  // Send batch
  public List<String> sendMessageBatch(List<Object> messages) 
    throws JsonProcessingException {
    List<SendMessageBatchRequestEntry> entries = new ArrayList<>();

    for (int i = 0; i < messages.size(); i++) {
      String messageJson = objectMapper.writeValueAsString(messages.get(i));

      entries.add(SendMessageBatchRequestEntry.builder()
        .id(String.valueOf(i))
        .messageBody(messageJson)
        .build());
    }

    SendMessageBatchRequest request = SendMessageBatchRequest.builder()
      .queueUrl(QUEUE_URL)
      .entries(entries)
      .build();

    SendMessageBatchResponse response = sqsClient.sendMessageBatch(request);

    return response.successful().stream()
      .map(SendMessageBatchResultEntry::messageId)
      .collect(Collectors.toList());
  }

  // Receive messages
  public List<Message> receiveMessages(int maxMessages) {
    ReceiveMessageRequest request = ReceiveMessageRequest.builder()
      .queueUrl(QUEUE_URL)
      .maxNumberOfMessages(maxMessages) // 1-10
      .waitTimeSeconds(20) // Long polling
      .messageAttributeNames("All")
      .build();

    ReceiveMessageResponse response = sqsClient.receiveMessage(request);
    return response.messages();
  }

  // Delete message (after processing)
  public void deleteMessage(String receiptHandle) {
    DeleteMessageRequest request = DeleteMessageRequest.builder()
      .queueUrl(QUEUE_URL)
      .receiptHandle(receiptHandle)
      .build();

    sqsClient.deleteMessage(request);
  }

  // Change message visibility (extend processing time)
  public void extendVisibilityTimeout(String receiptHandle, int seconds) {
    ChangeMessageVisibilityRequest request = 
      ChangeMessageVisibilityRequest.builder()
        .queueUrl(QUEUE_URL)
        .receiptHandle(receiptHandle)
        .visibilityTimeout(seconds)
        .build();

    sqsClient.changeMessageVisibility(request);
  }
}

// Message Consumer
@Component
public class OrderMessageConsumer {
  @Autowired
  private SqsService sqsService;

  @Autowired
  private OrderService orderService;

  @Scheduled(fixedDelay = 5000) // Poll every 5 seconds
  public void processMessages() {
    List<Message> messages = sqsService.receiveMessages(10);

    for (Message message : messages) {
      try {
        // Parse message
        OrderEvent event = objectMapper.readValue(
          message.body(), 
          OrderEvent.class
        );

        // Process
        orderService.processOrder(event);

        // Delete after successful processing
        sqsService.deleteMessage(message.receiptHandle());

      } catch (Exception e) {
        log.error("Failed to process message: " + message.messageId(), e);
        // Message returns to queue after visibility timeout
      }
    }
  }
}

// Producer example
@Service
public class OrderService {
  @Autowired
  private SqsService sqsService;

  public void placeOrder(Order order) {
    // Save to database
    orderRepository.save(order);

    // Send async processing message
    OrderEvent event = new OrderEvent(
      order.getId(),
      order.getCustomerId(),
      order.getItems()
    );

    sqsService.sendMessage(event);
  }
}
```

Best practices:
1. Use long polling (waitTimeSeconds=20) to reduce API calls
2. Delete messages only after successful processing
3. Use DLQ (Dead Letter Queue) for failed messages
4. Batch operations when possible (up to 10 messages)
5. Use visibility timeout to prevent duplicate processing
6. Set appropriate message retention (default 4 days, max 14 days)
7. Use presigned URLs for large files in S3 instead of streaming through app
